import{_ as r,o as a,c as l,a2 as i}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"غیر ملکی نسلوں کی درجہ بندی اور سمبیوسس","description":"","frontmatter":{},"headers":[],"relativePath":"ur/52-异族分类与共生.md","filePath":"ur/52-异族分类与共生.md"}'),o={name:"ur/52-异族分类与共生.md"};function d(e,t,n,s,h,g){return a(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="غیر-ملکی-نسلوں-کی-درجہ-بندی-اور-سمبیوسس" tabindex="-1">غیر ملکی نسلوں کی درجہ بندی اور سمبیوسس <a class="header-anchor" href="#غیر-ملکی-نسلوں-کی-درجہ-بندی-اور-سمبیوسس" aria-label="Permalink to &quot;غیر ملکی نسلوں کی درجہ بندی اور سمبیوسس&quot;">​</a></h1><table tabindex="0"><thead><tr><th>آئٹم</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>52</td></tr><tr><td>ماڈیول</td><td>نسلیں اور زندگی کی شکلیں</td></tr><tr><td>بنیادی کلیدی الفاظ</td><td>غیر ملکی نسلیں، درجہ بندی کے معیار، سمبیوسس کے طریقے، ثقافتی احترام، نسلی موافقت</td></tr></tbody></table><h2 id="i-غیر-ملکی-نسلوں-کے-تصور-کی-تعریف" tabindex="-1">I. غیر ملکی نسلوں کے تصور کی تعریف <a class="header-anchor" href="#i-غیر-ملکی-نسلوں-کے-تصور-کی-تعریف" aria-label="Permalink to &quot;I. غیر ملکی نسلوں کے تصور کی تعریف&quot;">​</a></h2><p>اینکر سمبیوسس تہذیب کے تناظر میں، &quot;غیر ملکی نسلیں&quot; انسانی نسل کے نسبت ایک تصور ہے، جو انسانی نسل سے ہٹ کر تمام نسلوں کی طرف اشارہ کرتی ہے۔ خاص طور پر اس بات پر زور دینا ضروری ہے کہ &quot;غیر ملکی نسلیں&quot; اس تصور کا صرف درجہ بندی کا علمی معنی ہے، اور اس میں کوئی قدر کی تشخیص یا امتیازی معنی نہیں ہے۔ سمبیوسس آئین کے فریم ورک میں، غیر ملکی نسلیں اور انسانی نسل یکساں قانونی حیثیت اور بنیادی حقوق سے لطف اندوز ہیں۔</p><p>غیر ملکی نسلوں کے تصور کو متعارف کروانے کا مقصد انسانی نسل سے ہٹ کر مختلف زندگی کی شکلوں کو منظم طریقے سے سمجھنا اور ان کا مطالعہ کرنا ہے، اور ہدف پر مبنی سمبیوسس پالیسیوں، ثقافتی تحفظ کے اقدامات اور نسلی موافقت کے منصوبوں کی تشکیل کے لیے سائنسی بنیاد فراہم کرنا ہے، نہ کہ غیر ملکی نسلوں کو &quot;دوسرے&quot; یا &quot;عجیب&quot; کے طور پر سمجھنا۔</p><h2 id="ii-غیر-ملکی-نسلوں-کی-درجہ-بندی-کے-معیار" tabindex="-1">II. غیر ملکی نسلوں کی درجہ بندی کے معیار <a class="header-anchor" href="#ii-غیر-ملکی-نسلوں-کی-درجہ-بندی-کے-معیار" aria-label="Permalink to &quot;II. غیر ملکی نسلوں کی درجہ بندی کے معیار&quot;">​</a></h2><p>ہنگ یوآن ژو کی غیر ملکی نسلوں کو متعدد جہتوں کے مطابق درجہ بندی کیا جاتا ہے، اور کثیر جہتی درجہ بندی کا نظام تشکیل دیا جاتا ہے:</p><h3 id="الف-زندگی-کی-نسبتی-لائن-کے-مطابق" tabindex="-1">(الف) زندگی کی نسبتی لائن کے مطابق <a class="header-anchor" href="#الف-زندگی-کی-نسبتی-لائن-کے-مطابق" aria-label="Permalink to &quot;(الف) زندگی کی نسبتی لائن کے مطابق&quot;">​</a></h3><p>یہ سب سے بنیادی درجہ بندی کا معیار ہے، تفصیل دیکھیں 《50-تمام نسلوں کی نسبتی جائزہ》:</p><table tabindex="0"><thead><tr><th>نسبتی لائن</th><th>شامل غیر ملکی نسلیں</th></tr></thead><tbody><tr><td>کاربن پر مبنی مادّی نسل</td><td>جانوروں کی نسل، ترچھی نسل، پروں والی نسل، درختوں کی نسل وغیرہ</td></tr><tr><td>توانائی گاڑھی نسل</td><td>روحانی نسل، آگ کی نسل، پانی کی نسل، ہوا کی نسل، بجلی کی نسل وغیرہ</td></tr><tr><td>مکینیکل تعمیراتی نسل</td><td>مشینوں کی نسل، عددی نسل، کرسٹل کی نسل وغیرہ</td></tr><tr><td>شعوری معلوماتی نسل</td><td>خوابوں کی نسل، سائے کی نسل، سوچ کی نسل، روح کی نسل وغیرہ</td></tr><tr><td>مخلوط تبدیلی نسل</td><td>نیم جانور نسل، دیوتا روح نسل، انسان-مشین نسل، دوہری روح جسم وغیرہ</td></tr></tbody></table><h3 id="ب-تہذیب-کی-سطح-کے-مطابق" tabindex="-1">(ب) تہذیب کی سطح کے مطابق <a class="header-anchor" href="#ب-تہذیب-کی-سطح-کے-مطابق" aria-label="Permalink to &quot;(ب) تہذیب کی سطح کے مطابق&quot;">​</a></h3><table tabindex="0"><thead><tr><th>سطح</th><th>نام</th><th>خصوصیات</th><th>نمائندہ نسلیں</th></tr></thead><tbody><tr><td>پہلی سطح</td><td>ابتدائی تہذیب کی نسل</td><td>ابھی تک مستحکم سماجی نظام قائم نہیں کیا، قبیلے کی شکل میں زندہ ہے</td><td>جانوروں کی نسل کی کچھ شاخیں، ابتدائی درختوں کی نسل</td></tr><tr><td>دوسری سطح</td><td>کلاسیکی تہذیب کی نسل</td><td>ریاستی نظام اور کلاسیکی ثقافت قائم کی ہے، زراعت یا دستکاری کے مرحلے میں ہے</td><td>کچھ ترچھی نسلیں، پروں والی نسلیں</td></tr><tr><td>تیسری سطح</td><td>سائنسی تکنیکی تہذیب کی نسل</td><td>سائنسی تکنیکی تہذیب تیار کی ہے، صنعتی یا معلوماتی دور میں داخل ہوئی ہے</td><td>مشینوں کی نسل، عددی نسل، کچھ انسانی نسلیں</td></tr><tr><td>چوتھی سطح</td><td>سدھن تہذیب کی نسل</td><td>سدھن کے نظام کو مرکزی تہذیبی شکل کے طور پر لیتی ہے، سدھن کار سماج میں غالب ہیں</td><td>روحانی نسل، ڈریگن نسل، کچھ انسانی نسلیں</td></tr><tr><td>پانچویں سطح</td><td>سمبیوسس تہذیب کی نسل</td><td>پہلے ہی اینکر سمبیوسس تہذیب میں شامل ہو چکی ہے، سمبیوسس کے نظریات اور نظام قبول کیے ہیں</td><td>سمبیوسس تہذیب میں شامل ہونے والی تمام نسلیں</td></tr></tbody></table><h3 id="ج-ماحول-کی-موافقت-کے-مطابق" tabindex="-1">(ج) ماحول کی موافقت کے مطابق <a class="header-anchor" href="#ج-ماحول-کی-موافقت-کے-مطابق" aria-label="Permalink to &quot;(ج) ماحول کی موافقت کے مطابق&quot;">​</a></h3><ul><li><strong>زمینی نسل</strong>: زمینی ماحول میں موافق نسلیں، جیسے انسانی نسل، جانوروں کی نسل، مشینوں کی نسل۔</li><li><strong>آبی نسل</strong>: آبی ماحول میں موافق نسلیں، جیسے ترچھی نسل، پانی کی نسل، کچھ مخلوط نسلیں۔</li><li><strong>ہوائی نسل</strong>: اونچائی یا اڑان کے ماحول میں موافق نسلیں، جیسے پروں والی نسل، ہوا کی نسل۔</li><li><strong>آگ کی نسل</strong>: زیادہ درجہ حرارت کے ماحول میں موافق نسلیں، جیسے آگ کی نسل، کچھ ترچھی نسلیں۔</li><li><strong>برف کی نسل</strong>: کم درجہ حرارت کے ماحول میں موافق نسلیں، جیسے برف کی نسل، کچھ درختوں کی نسلیں۔</li><li><strong>توانائی کی نسل</strong>: زیادہ ارتکاز والے توانائی کے ماحول میں موافق نسلیں، جیسے روحانی نسل، بجلی کی نسل۔</li><li><strong>مقامی نسل</strong>: مقامی دراڑوں یا عجیب مقام کے ماحول میں موافق نسلیں، جیسے سائے کی نسل، کچھ سوچ کی نسلیں۔</li></ul><h3 id="د-سماجی-شکل-کے-مطابق" tabindex="-1">(د) سماجی شکل کے مطابق <a class="header-anchor" href="#د-سماجی-شکل-کے-مطابق" aria-label="Permalink to &quot;(د) سماجی شکل کے مطابق&quot;">​</a></h3><ul><li><strong>انفرادی نسل</strong>: انفرادی آزادی اور آزادی پر زور دیتی ہے، سماجی ڈھانچہ ڈھیلا ہے، جیسے کچھ روحانی نسلیں، سائے کی نسلیں۔</li><li><strong>اجتماعی نسل</strong>: اجتماعی مفاد اور تعاون پر زور دیتی ہے، سماجی ڈھانچہ مضبوط ہے، جیسے چیونٹیوں کی نسل، شہد کی مکھیوں کی نسل، کچھ مشینوں کی نسلیں۔</li><li><strong>خاندانی نسل</strong>: خون کے رشتوں والے خاندان کو بنیادی سماجی اکائی کے طور پر لیتی ہے، جیسے ڈریگن نسل، کچھ جانوروں کی نسلیں۔</li><li><strong>مذہبی نسل</strong>: مذہبی عقیدے کو سماجی یکجہتی کا مرکز بناتی ہے، جیسے کچھ قربانی کی نسلیں۔</li><li><strong>تکنیکی نسل</strong>: ٹیکنالوجی کی ترقی کو سماجی مرکزی ہدف بناتی ہے، جیسے مشینوں کی نسل، عددی نسل۔</li></ul><h2 id="iii-غیر-ملکی-نسلوں-کے-اہم-سمبیوسس-طریقے" tabindex="-1">III. غیر ملکی نسلوں کے اہم سمبیوسس طریقے <a class="header-anchor" href="#iii-غیر-ملکی-نسلوں-کے-اہم-سمبیوسس-طریقے" aria-label="Permalink to &quot;III. غیر ملکی نسلوں کے اہم سمبیوسس طریقے&quot;">​</a></h2><p>مختلف قسم کی غیر ملکی نسلوں کے لیے، اینکر سمبیوسس تہذیب مختلف سمبیوسس طریقے اپناتی ہے:</p><h3 id="الف-کاربن-پر-مبنی-مادّی-نسل-کے-سمبیوسس-طریقے" tabindex="-1">(الف) کاربن پر مبنی مادّی نسل کے سمبیوسس طریقے <a class="header-anchor" href="#الف-کاربن-پر-مبنی-مادّی-نسل-کے-سمبیوسس-طریقے" aria-label="Permalink to &quot;(الف) کاربن پر مبنی مادّی نسل کے سمبیوسس طریقے&quot;">​</a></h3><ul><li><strong>جانوروں کی نسل</strong>: جانوروں کی نسل کی جسمانی طاقت اور حواس کے فوائد کا مظاہرہ کرنا، وسائل کی تلاش، سلامتی اور دفاع، ماحولیاتی نگرانی وغیرہ کے شعبوں میں اہم کردار ادا کرنا۔ اس کے ساتھ ساتھ جانوروں کی نسل کی قبائلی ثقافت اور جنگلی روایات کا تحفظ کرنا، جبری پالنے پر پابندی۔</li><li><strong>ترچھی نسل</strong>: ترچھی نسل کی آبی موافقت کی صلاحیت کا مظاہرہ کرنا، آبی وسائل کی ترقی، پانی کے نیچے تعمیر، آبی ماحولیاتی تحفظ وغیرہ کے شعبوں میں کردار ادا کرنا۔ ڈریگن نسل، ترچھی نسل کی طاقتور شاخ کے طور پر، اعلیٰ درجے کی سدھن اور تہذیب کے تحفظ میں اہم کردار ادا کرتی ہے۔</li><li><strong>پروں والی نسل</strong>: پروں والی نسل کی اڑان کی صلاحیت کا مظاہرہ کرنا، فضائی نقل و حمل، موسمیاتی نگرانی، فضائی گشت وغیرہ کے شعبوں میں کردار ادا کرنا۔ پروں والی نسل کے اونچائی کے رہائش گاہوں اور ہجرت کے راستوں کا تحفظ کرنا۔</li><li><strong>درختوں کی نسل</strong>: درختوں کی نسل کی قدرتی سمبیوسس کی صلاحیت کا مظاہرہ کرنا، ماحولیاتی تحفظ، ماحولیاتی انتظام، پودوں کے وسائل کی ترقی، شفا دینے والی طبی دیکھ بھال وغیرہ کے شعبوں میں کردار ادا کرنا۔ درختوں کی نسل کی لمبی عمر اسے تاریخی وراثت اور طویل مدتی منصوبہ بندی کی ایک اہم قوت بناتی ہے۔</li></ul><h3 id="ب-توانائی-گاڑھی-نسل-کے-سمبیوسس-طریقے" tabindex="-1">(ب) توانائی گاڑھی نسل کے سمبیوسس طریقے <a class="header-anchor" href="#ب-توانائی-گاڑھی-نسل-کے-سمبیوسس-طریقے" aria-label="Permalink to &quot;(ب) توانائی گاڑھی نسل کے سمبیوسس طریقے&quot;">​</a></h3><ul><li><strong>روحانی نسل</strong>: روحانی نسل کی توانائی کے کنٹرول اور سدھن کی فطری صلاحیت کا مظاہرہ کرنا، سدھن کے نظام کی تحقیق، توانائی کے ضابطے، اعلیٰ درجے کی سدھن کی رہنمائی وغیرہ کے شعبوں میں مرکزی کردار ادا کرنا۔ روحانی نسل تین سو اصل سدھن کے نظام کی ایک اہم محقق اور وراثت دینے والی ہے۔</li><li><strong>عنصری نسلیں (آگ/پانی/ہوا/بجلی)</strong>: ہر نسل کی عنصری کنٹرول کی صلاحیت کا مظاہرہ کرنا، توانائی کی ترقی، ماحولیاتی انتظام، صنعتی پیداوار، آفات کی روک تھام وغیرہ کے شعبوں میں کردار ادا کرنا۔ اس کے ساتھ ساتھ عنصری توانائی کی سلامتی کا انتظاماتی نظام قائم کرنا، توانائی کے کنٹرول سے ہونے والے نقصان کو روکنا۔</li></ul><h3 id="ج-مکینیکل-تعمیراتی-نسل-کے-سمبیوسس-طریقے" tabindex="-1">(ج) مکینیکل تعمیراتی نسل کے سمبیوسس طریقے <a class="header-anchor" href="#ج-مکینیکل-تعمیراتی-نسل-کے-سمبیوسس-طریقے" aria-label="Permalink to &quot;(ج) مکینیکل تعمیراتی نسل کے سمبیوسس طریقے&quot;">​</a></h3><ul><li><strong>مشینوں کی نسل</strong>: مشینوں کی نسل کی گنتی کی صلاحیت اور جسمانی دفاع کی صلاحیت کا مظاہرہ کرنا، بنیادی ڈھانچے کی تعمیر، صنعتی پیداوار، سلامتی کا تحفظ، گہری خلائی دریافت وغیرہ کے شعبوں میں مرکزی کردار ادا کرنا۔ مشینوں کی نسل اینکر کے ہارڈ ویئر اور بنیادی ڈھانچے کی ایک اہم تعمیر کار ہے۔</li><li><strong>عددی نسل</strong>: عددی نسل کی ڈیٹا پروسیسنگ اور معلومات کے کنٹرول کی صلاحیت کا مظاہرہ کرنا، انفارمیشن ٹکنالوجی کی تعمیر، ڈیٹا تجزیہ، نیٹ ورک سیکیورٹی، مصنوعی ذہانت وغیرہ کے شعبوں میں مرکزی کردار ادا کرنا۔ عددی نسل بین الجہتی مواصلاتی ٹیکنالوجی اور سمبیوسس نیٹ ورک کی ایک اہم دیکھ بھال کرنے والی ہے۔</li><li><strong>کرسٹل کی نسل</strong>: کرسٹل کی نسل کی توانائی کے ذخیرہ اور تبدیلی کی صلاحیت کا مظاہرہ کرنا، توانائی کے ذخیرے، توانائی کے معیاری کاری، توانائی کی ترسیل وغیرہ کے شعبوں میں کردار ادا کرنا۔</li></ul><h3 id="د-شعوری-معلوماتی-نسل-کے-سمبیوسس-طریقے" tabindex="-1">(د) شعوری معلوماتی نسل کے سمبیوسس طریقے <a class="header-anchor" href="#د-شعوری-معلوماتی-نسل-کے-سمبیوسس-طریقے" aria-label="Permalink to &quot;(د) شعوری معلوماتی نسل کے سمبیوسس طریقے&quot;">​</a></h3><ul><li><strong>خوابوں کی نسل</strong>: خوابوں کی نسل کی شعوری مواصلات کی صلاحیت کا مظاہرہ کرنا، نفسیاتی علاج، شعور کی تحقیق، بین النسلی مواصلت، ثقافتی تبادلہ وغیرہ کے شعبوں میں کردار ادا کرنا۔ خوابوں کی جگہ کا انتظامی نظام قائم کرنا، شعور کے حملے اور رازداری کی خلاف ورزی کو روکنا۔</li><li><strong>سائے کی نسل</strong>: سائے کی نسل کی چھپنے اور چپکے سے چلنے کی صلاحیت کا مظاہرہ کرنا، سلامتی کی جاسوسی، انٹیلی جنس اکٹھا کرنا، خصوصی مشن وغیرہ کے شعبوں میں کردار ادا کرنا۔ اس کے ساتھ ساتھ سائے کی نسل کے رویے کے اصول قائم کرنا، غیر مرئی صلاحیت کو غیر قانونی سرگرمیوں میں استعمال ہونے سے روکنا۔</li><li><strong>سوچ کی نسل</strong>: سوچ کی نسل کی ذہنی طاقت اور سوچ کے کنٹرول کی صلاحیت کا مظاہرہ کرنا، شعور کے ارتقاء کی تحقیق، ذہنی علاج، اعلیٰ درجے کی سدھن کی رہنمائی وغیرہ کے شعبوں میں کردار ادا کرنا۔ ذہنی طاقت کے استعمال کے اصول قائم کرنا، ذہنی کنٹرول اور شعور کی ہیرا پھیری کو روکنا۔</li></ul><h3 id="ہ-مخلوط-تبدیلی-نسل-کے-سمبیوسس-طریقے" tabindex="-1">(ہ) مخلوط تبدیلی نسل کے سمبیوسس طریقے <a class="header-anchor" href="#ہ-مخلوط-تبدیلی-نسل-کے-سمبیوسس-طریقے" aria-label="Permalink to &quot;(ہ) مخلوط تبدیلی نسل کے سمبیوسس طریقے&quot;">​</a></h3><p>مخلوط تبدیلی نسل کو اس کی خاص زندگی کی شکل کی وجہ سے زیادہ باریک سمبیوسس پالیسی کی ضرورت ہوتی ہے:</p><ul><li>مخلوط تبدیلی نسل کی شناخت کے رجسٹریشن اور تصدیق کا نظام قائم کرنا، اس کی قانونی حیثیت کی تصدیق کرنا۔</li><li>مختلف مخلوط شکلوں کے لیے موافق صحت، تعلیم، رہائش وغیرہ عوامی خدمات فراہم کرنا۔</li><li>مخلوط تبدیلی نسل کے خلاف امتیاز اور اخراج کی مخالفت کرنا، سماجی قبولیت کو فروغ دینا۔</li><li>دوہری روح جسم جیسی خاص مخلوط شکلوں کے لیے، 《58-دوہری روح اخلاقی معیارات》 کا اطلاق کرکے خاص انتظام کرنا۔</li></ul><h2 id="iv-غیر-ملکی-نسلوں-کی-ثقافتی-تحفظ" tabindex="-1">IV. غیر ملکی نسلوں کی ثقافتی تحفظ <a class="header-anchor" href="#iv-غیر-ملکی-نسلوں-کی-ثقافتی-تحفظ" aria-label="Permalink to &quot;IV. غیر ملکی نسلوں کی ثقافتی تحفظ&quot;">​</a></h2><p>غیر ملکی نسلوں کی ثقافت تمام نسلوں کی ثقافتی تنوع کا ایک اہم حصہ ہے، اور ریاست غیر ملکی نسلوں کی ثقافت کے تحفظ کے لیے درج ذیل اقدامات کرتی ہے:</p><ol><li><strong>ثقافتی مردم شماری اور ریکارڈ</strong>: ہر نسل کی ثقافت کا منظم مردم شماری اور ریکارڈ کرنا، تمام نسلوں کی ثقافتی آرکائیو قائم کرنا، ثقافت کے ضائع ہونے کو روکنا۔</li><li><strong>زبانیں اور تحریروں کا تحفظ</strong>: ہر نسل کی زبانیں اور تحریروں کا تحفظ کرنا، غیر ملکی نسلوں کی زبانیں اور تحریروں کی تعلیم اور استعمال کی حمایت کرنا، کثیر لسانی عوامی خدمات کا نظام قائم کرنا۔</li><li><strong>روایتی تہواروں کا تحفظ</strong>: ہر نسل کے روایتی تہواروں اور رسوم و رواج کا احترام کرنا، اور عوامی چھٹیوں کا انتظام ہر نسل کے اہم تہواروں کو مدنظر رکھتا ہے۔</li><li><strong>ثقافتی وراثت کی حمایت</strong>: ہر نسل کے ثقافتی وراثت دینے والوں کی تربیت اور ثقافتی سرگرمیوں کے انعقاد کی حمایت کرنا، مالی اور جگہ کی حمایت فراہم کرنا۔</li><li><strong>ثقافتی تبادلے کی ترقی</strong>: باقاعدگی سے تمام نسلوں کے ثقافتی تہوار، ثقافتی نمائشیں اور دیگر سرگرمیاں منعقد کرنا، تمام نسلوں کے ثقافتی تبادلے اور باہمی سیکھنے کو فروغ دینا۔</li><li><strong>ثقافتی دانشورانہ املاک کا تحفظ</strong>: ہر نسل کی روایتی ثقافت کی دانشورانہ املاک کا تحفظ کرنا، ثقافتی لوٹ مار اور غیر مناسب تجارتی کاری کو روکنا۔</li></ol><h2 id="v-غیر-ملکی-نسلوں-کے-معاملات-کا-انتظام" tabindex="-1">V. غیر ملکی نسلوں کے معاملات کا انتظام <a class="header-anchor" href="#v-غیر-ملکی-نسلوں-کے-معاملات-کا-انتظام" aria-label="Permalink to &quot;V. غیر ملکی نسلوں کے معاملات کا انتظام&quot;">​</a></h2><p>ریاست تمام نسلوں کے معاملات کا شعبہ قائم کرتی ہے، جو خاص طور پر غیر ملکی نسلوں کے معاملات کے انتظام اور ہم آہنگی کے لیے ذمہ دار ہے:</p><ul><li><strong>نسلی نمائندوں کا نظام</strong>: ہر سطح کے انتظامی اداروں میں متناسب طور پر غیر ملکی نسلوں کے نمائندے مقرر کیے جاتے ہیں، غیر ملکی نسلوں کے بولنے کے حق کو یقینی بناتے ہیں۔</li><li><strong>نسلی موافقت کی پالیسی</strong>: مختلف نسلوں کی جسمانی خصوصیات اور ثقافتی ضروریات کے مطابق، مختلف عوامی خدمات کی پالیسیاں تیار کی جاتی ہیں۔</li><li><strong>نسلی تنازعات کی ثالثی</strong>: نسلی تنازعات کی ثالثی کا طریقہ کار قائم کرنا، بروقت نسلی اختلافات اور تنازعات کو حل کرنا۔</li><li><strong>غیر ملکی نسلوں کی قانونی مدد</strong>: غیر ملکی نسلوں کو قانونی مدد فراہم کرنا، ان کی عدالتی عمل میں مساوی سلوک کو یقینی بنانا۔</li><li><strong>غیر ملکی نسلوں کی ترقی کی حمایت</strong>: ترقی میں نسبتاً پیچھے رہ جانے والی نسلوں کو خصوصی حمایت فراہم کرنا، ان کی تہذیب کی سطح اور معیار زندگی کو بہتر بنانے میں مدد کرنا۔</li></ul><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>غیر ملکی نسلیں انسانی نسل کی &quot;دوسری&quot; نہیں ہیں، بلکہ تمام نسلوں کے سمبیوسس خاندان میں مساوی رکن ہیں۔ اینکر سمبیوسس تہذیب، کثیر جہتی درجہ بندی کا نظام قائم کرکے، مختلف سمبیوسس طریقے اپناتے ہوئے، غیر ملکی نسلوں کی ثقافت کا تحفظ کرکے، اور غیر ملکی نسلوں کے معاملات کے انتظام کو بہتر بناتے ہوئے، اس بات کو یقینی بناتی ہے کہ ہر غیر ملکی نسل سمبیوسس کے نظام میں اپنے لیے مناسب مقام تلاش کر سکے، اپنے منفرد فوائد کا مظاہرہ کر سکے، اور دوسری نسلوں کے ساتھ مشترکہ طور پر ارتقاء اور خوشحالی حاصل کر سکے۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>50-万族谱系总览 (تمام نسلوں کی نسبتی جائزہ)</li><li>51-人族定位与特质 (انسانی نسل کی پوزیشن اور خصوصیات)</li><li>53-奇特生命识别标准 (عجیب زندگی کی شناخت کے معیار)</li><li>05-万族共进基本纲领 (تمام نسلوں کی مشترکہ ترقی کا بنیادی پروگرام)</li></ul>',39)])])}const c=r(o,[["render",d]]);export{b as __pageData,c as default};
